const items = $input.all();
const priceRows = [];
const txRows = [];

for (const it of items) {
  const j = it.json || {};
  if (j.brand) priceRows.push(j);
  else if (j.invoice_id) txRows.push(j);
}

const today = $now.toFormat('yyyy-MM-dd');

const priceLines = priceRows.map(function (p) {
  const promoActive = String(p.promo_active || '').toUpperCase() === 'TRUE';
  const promo = p.promo_price && p.promo_price !== '' ? '$' + p.promo_price : 'none';
  return '  - ' + p.brand +
    ' | ' + (p.product || '-') +
    ' | list $' + p.list_price +
    ' | promo ' + promo + (promoActive ? ' [PROMO ACTIVE]' : '') +
    ' | est. weekly vol ' + p.est_weekly_volume +
    ' | unit cost $' + p.unit_cost +
    ' | segment ' + (p.segment || '-') +
    ' | channel ' + (p.channel || '-');
}).join('\n');

const txLines = txRows.map(function (t) {
  return '  - ' + t.invoice_id +
    ' | ' + (t.product || '-') +
    ' | qty ' + t.qty +
    ' | net $' + t.net_price +
    ' | cost $' + t.unit_cost +
    ' | margin contrib $' + t.margin_contrib;
}).join('\n');

const prompt = [
  'You are a senior Pricing & Revenue Growth Management consultant supporting a strategy engagement at a large consumer company.',
  '',
  'CONTEXT',
  '- Market: home coffee pods (illustrative sample data - replace with your own files)',
  '- Report date: ' + today,
  '- Our brand: AuroraRoast',
  '- This is the weekly pricing intelligence and steering brief.',
  '',
  '1) COMPETITIVE PRICING SNAPSHOT (from sample_competitive_prices.csv)',
  priceLines || '  (no rows)',
  '',
  '2) TRANSACTION-LEVEL MARGIN ANALYSIS (from sample_transactions.csv)',
  txLines || '  (no rows)',
  '',
  'PRODUCE A STEERING-READY MEMO (Markdown, no code fences) with these sections:',
  '1. Executive summary (4-6 bullets)',
  '2. Competitive pricing snapshot: positioning vs AuroraRoast, promo activity, price gaps, threats',
  '3. Margin & transaction analysis: margin contribution by product, outliers, discount-leakage signals',
  '4. Value-based pricing opportunities: economic value drivers and willingness-to-pay signals visible in the data; where value-based pricing (incl. EVE logic) could lift margin',
  '5. Customer segmentation implications: premium vs value segments, where to hold price vs defend share',
  '6. Recommended actions: exactly 3, each with owner (pricing/commercial/finance), effort (low/med/high), expected impact',
  '7. Risks & what to monitor next week',
  'Keep it under 500 words, concrete, reference the numbers given, and never invent figures not in the data.'
].join('\n');

return [{ json: { prompt: prompt, today: today } }];

const input = $input.all();
const item = input.length ? (input[0].json || {}) : {};
const memoText = (item.message && item.message.content)
  ? item.message.content
  : JSON.stringify(item);
const today = $now.toFormat('yyyy-MM-dd');
const filename = 'pricing-memo-' + today + '.md';
return [{ json: { data: memoText, filename: filename, memo: memoText } }];
